const gen = $('Call Module API - Generate').item.json;
const plan = gen.summary || {};
const counts = plan.counts || {};
const variants = plan.variants || {};
function pickSubject(seg) {
  const v = variants[seg] || {};
  return v.subject_a || v.subject || 'n/a';
}
const resumeUrl = $('Respond Awaiting Approval').item.json.approve_url;
const eventSlug = $('M2 Run (webhook)').item.json.body.event_slug;
const lines = [
  'M2 dispatch plan ready for ' + eventSlug + ' (run ' + gen.run_id + ').',
  '',
  'Counts: attendee=' + (counts.attendee ?? '?') + ', no_show=' + (counts.no_show ?? '?') + ', speaker=' + (counts.speaker ?? '?') + ', mailable=' + (counts.mailable ?? '?') + ', suppressed=' + (counts.suppressed ?? '?'),
  '',
  'Subjects:',
  '  attendee: ' + pickSubject('attendee'),
  '  no_show: ' + pickSubject('no_show'),
  '  speaker: ' + pickSubject('speaker'),
  '',
  'Approve within 24h by running:',
  'curl -X POST ' + resumeUrl + ' -H "Content-Type: application/json" -d \'{"approved_by":"<you>","mode":"demo"}\''
];
return [{ json: {
  to: $('M2 Run (webhook)').item.json.body.approver_email,
  subject: '[M2 Approval] ' + eventSlug + ' dispatch ready',
  body_text: lines.join('\n')
} }];

const recipient = $('Batch Recipients (1)').item.json;
const resp = $json.body || $json;
return [{ json: {
  email: recipient.email,
  segment: recipient.segment,
  provider: 'hubspot',
  message_id: resp.statusId || null,
  sent_to: recipient.demo_redirect_to || recipient.email,
  sent_at: new Date().toISOString(),
  status: 'sent',
  error: null
} }];

const recipient = $('Batch Recipients (1)').item.json;
const resp = $json;
const failed = Boolean(resp.error);
return [{ json: {
  email: recipient.email,
  segment: recipient.segment,
  provider: 'gmail',
  message_id: resp.id || null,
  sent_to: recipient.demo_redirect_to || recipient.email,
  sent_at: new Date().toISOString(),
  status: failed ? 'failed' : 'sent',
  error: failed ? (resp.error.message || String(resp.error)) : null
} }];

const hubspotRows = $('Map HubSpot Result').all().map(i => i.json);
const gmailRows = $('Map Gmail Result').all().map(i => i.json);
const results = [...hubspotRows, ...gmailRows];
const runId = $('Call Module API - Approve').item.json.run_id || $('Call Module API - Generate').item.json.run_id;
return [{ json: { run_id: runId, results } }];

const gen = $('Call Module API - Generate').item.json;
const appr = $('Call Module API - Approve').item.json;
const logResp = $json;
const rows = $('Aggregate Dispatch Results').item.json.results || [];

const sentRows = rows.filter(r => r.status === 'sent');
const failedRows = rows.filter(r => r.status === 'failed');
const sentTimes = sentRows.map(r => Date.parse(r.sent_at)).filter(t => !isNaN(t));
const firstSendTs = sentTimes.length ? new Date(Math.min.apply(null, sentTimes)).toISOString() : null;

const eventCloseTs = (gen.summary || {}).event_close_ts || null;
let hoursAfterClose = null;
if (firstSendTs && eventCloseTs) {
  hoursAfterClose = (Date.parse(firstSendTs) - Date.parse(eventCloseTs)) / 3600000;
}

const providers = Array.from(new Set(rows.map(r => r.provider)));

const summary = {
  run_id: gen.run_id,
  mode: $('M2 Run (webhook)').item.json.body.mode,
  event_close_ts: eventCloseTs,
  first_send_ts: firstSendTs,
  hours_after_close: hoursAfterClose,
  sent: sentRows.length,
  failed: failedRows.length,
  logged: (logResp.summary || {}).logged ?? sentRows.length,
  skipped: rows.length - sentRows.length - failedRows.length,
  providers: providers,
  receipts: [].concat(gen.receipts || [], appr.receipts || [], logResp.receipts || [])
};

const fileName = summary.run_id + '-m2.json';
const fileContent = Buffer.from(JSON.stringify(summary, null, 2), 'utf8').toString('base64');

return [{ json: summary, binary: { data: { data: fileContent, mimeType: 'application/json', fileName: fileName } } }];
